    if($null -ne $tgt -and [string]$tgt -match '"'\\uFFFD'){"'$issues += "replacement id=$($i.id) field=$prop"}
  }
}
if($issues.Count){$issues}else{'"'TARGET_SCAN_OK: no blanks, Bengali script, unintended Latin letters, non-ASCII digits, or replacement characters'}"

